import pty,os,re
def run(args,env,cwd=None):
    out=[]
    pid,fd=pty.fork()
    if pid==0:
        if cwd: os.chdir(cwd)
        os.execve('/tmp/ref/crowbook',['/tmp/ref/crowbook']+args,env)
    try:
        while True:
            d=os.read(fd,4096)
            if not d: break
            out.append(d)
    except OSError: pass
    os.waitpid(pid,0)
    return b''.join(out)
base=dict(os.environ); base['TERM']='xterm-256color'; base.pop('LANG',None)
def clean(d):
    s=d.decode('utf-8',errors='replace')
    s=re.sub(r'\x1b\[[0-9;?]*[A-Za-z]','',s)
    seen=[]
    for part in re.split(r'[\r\n]+',s):
        p=part.rstrip()
        p=re.sub(r'^[-\\|/] ','SPIN ',p)
        if p and p not in seen and '░' not in p and '█' not in p: seen.append(p)
    return seen
for L in ['en','fr']:
    d=run(['-L',L,'bd_en.crowbook'],base,'/tmp/work/i18n/full')
    print('== html.dir',L)
    for l in clean(d): print('   ',repr(l))
